import fs from 'node:fs';

const born = JSON.parse(fs.readFileSync('/tmp/claude-0/prov-research/born116.json', 'utf8'));
const clean = (t) => t.split(/\s*[–—]\s*/)[0].replace(/\s+$/, '');
const L = [];
const defaults = (lines) => { L.push('```entry-defaults'); lines.forEach((l) => L.push(l)); L.push('```', ''); };
const entry = (el, head, lines) => { L.push('```entry ' + el); L.push('## ' + head); lines.forEach((l) => L.push(l)); L.push('```', ''); };

L.push('# research-project - edited backfill brief', '');

// --- #116
L.push('## PR #116 - 2026-07-04 - the playbook enters the corpus', '');
defaults([
  "- **Source:** the gRatio project's `docs/research_process_playbook.md`, lifted verbatim as the first entry in a project-type templates catalog and scrubbed of the one project-specific path it hardcoded.",
  '- **Actor:** @missingbulb (owner).',
  '- **Landed:** #116 (Closes #115).',
]);
entry('_pack', '2026-07-04 · born · Project-type templates catalog + categorize-at-bootstrap flow (#116)', [
  "- **Reason:** the owner runs one class of project repeatedly - an algorithm over similarly-formatted inputs, scored against annotated ground truth, improved in reviewable iterations - and the working procedure for it existed only inside one project. A catalog of one playbook per class gave the class a home a fresh project is matched against at bootstrap.",
  "- **Mechanism:** a project-agnostic template under `templates/`, linked from a matching project's own CLAUDE.md at bootstrap and left the single source of truth for the class; packs, checks and skills did not exist yet.",
  '- **Rejected:** copying the playbook into each project, which is what the lift replaced: the catalog entry is linked, so the class has one text rather than a copy per repository.',
]);
for (const b of born) {
  entry(b.el, b.head, ['- **Mechanism:** a rule of the playbook template `templates/research-project.md`, triggered on "' + clean(b.trigger) + '".']);
}

// --- #128
L.push('## PR #128 - 2026-07-06 - the template becomes a pack', '');
defaults(['- **Actor:** @missingbulb (owner).', '- **Landed:** #128 (Closes #127, Closes #131) · pack version 1.']);
entry('_pack', '2026-07-06 · moved · becomes the pack `research-project` (#128)', [
  '- **Reason:** the context-relief architecture replaced always-loaded corpus files with two homes selected by when a rule is active, and `templates/` was folded into `packs/` with `always/`, `tasks/` and `technologies/`. The playbook crossed unchanged: `packs/research-project/RULES.md` at this commit is byte-identical to the template it replaced.',
  '- **Mechanism:** the pack manifest, declared and never fingerprinted - what a repository holds says nothing about whether the work in it is this class of research, so a project declares the pack the way it used to link the template. All fourteen sections stay prose: methodology and judgment, with no static signature a check could read.',
  '- **Rejected:** splitting the class along the seams the manifest header names, session continuity and reading source articles, which stay noted as future splits rather than packs of their own.',
]);

// --- #222
L.push('## PR #222 - 2026-07-11 - growth promote', '');
defaults([
  "- **Source:** the gRatio project's local docs, read by the 2026-07-11 growth-promote run.",
  '- **Actor:** the growth-promote run, merged by @missingbulb (owner).',
  '- **Landed:** #222 (Refs #99) · pack version 1.',
]);
entry('beat-naive-baseline', '2026-07-11 · born · Growth promote (2026-07-11): portable lessons into canon (#222)', [
  '- **Reason:** sophistication is not accuracy: when the guiding signal is noisy or penetrates the structure unevenly, a “smarter” local correction can measurably lose to a plain uniform one, so the naive baseline is kept as the thing to beat rather than assumed beaten.',
  '- **Mechanism:** a RULES.md rule, triggered on "Beat the naive baseline, or drop it.".',
  '- **Rejected:** a check - every candidate of the run landed at the prose rung, each being judgment or platform knowledge with no clean static signature authorable and fixture-able unattended.',
]);

// --- #467
L.push('## PR #467 - 2026-07-27 - the tightening sweep', '');
defaults([
  '- **Reason:** the sweep cut from every rule in the corpus the consequence prose arguing for a rule rather than enabling it, leaving each as trigger, instruction and at most one clause of why, kept only where the rule would otherwise land as ceremony a reader skips. This pack went from 3,299 words to 3,127, corpus-wide 17,127 to 15,220. No rule was merged or dropped, and every path, command and concrete detail stayed.',
  '- **Actor:** @missingbulb (owner).',
  '- **Landed:** #467 (Closes #466) · pack version 1.',
]);
for (const el of ['beat-naive-baseline', 'explicitly-record-approach', 'fresh-container-has', 'keep-registry-domain', 'name-hard-constraint', 'owner-asks-different', 'respect-validation-tiers', 'take-suggestion-seriously', 'tried-rejected']) {
  entry(el, '2026-07-27 · reworded · Tighten every RULES.md to when + what + one non-obvious fact (#467)', []);
}

// --- #497
L.push('## PR #497 - 2026-07-28 - growth promote', '');
defaults([
  "- **Source:** the VascularColoring project's local pack, read by the 2026-07-27 growth-promote run.",
  '- **Actor:** the growth-promote run, merged by @missingbulb (owner).',
  '- **Landed:** #497 (Refs #99) · pack version 1.',
]);
entry('draw-annotation-colour', "2026-07-28 · born · Growth: promote 5 lessons from the fleet's local packs (#497)", [
  "- **Reason:** a mark in the signal's own colour disappears exactly on the objects it exists to mark, so the figure looks cleanest where the method is least verified.",
  '- **Mechanism:** a RULES.md rule, triggered on "Never draw an annotation in a colour the underlying signal itself carries.".',
  "- **Rejected:** a check - the grounded case is checkable, but only against a project's own render script, and the generalized palette rule has no target to scan. It stays a local check in the member it came from.",
]);
entry('show-method-breaks', "2026-07-28 · born · Growth: promote 5 lessons from the fleet's local packs (#497)", [
  '- **Reason:** promoted at the prose rung - in-flight judgment about how a result is presented, with no repo-state signature a conformance check could carry.',
