mkdir -p /tmp/claude-0/scratch && cat > /tmp/claude-0/scratch/add-model.mjs <<'EOF'
// Adds the `Model:` line to backfilled provenance entries, deriving it exactly as
// provenance.mjs does (MODEL_TRAILER + the >1 generic-Claude drop) so these packs
// spell it the same way as the rest of the shelf. An entry whose commit carries no
// trailer gets no line: an unknown model is a state, never a guess.
import { execFileSync } from 'node:child_process';
import { readFileSync, writeFileSync, readdirSync } from 'node:fs';

const [root, dir] = process.argv.slice(2);
const git = (...a) => execFileSync('git', ['-C', root, ...a], { encoding: 'utf8', maxBuffer: 1 << 28 });
const MODEL_TRAILER = /^co-authored-by:\s*(Claude\b[^<]*?)\s*</i;

const byPr = new Map();
for (const rec of git('log', 'main', '--format=%H%x00%s%x00%b%x01').split('\x01')) {
  const [sha, subject, body] = rec.replace(/^\n/, '').split('\x00');
  if (!sha) continue;
  const m = /\(#(\d+)\)\s*$/.exec(subject ?? '');
  if (!m) continue;
  const models = new Set();
  for (const l of (body ?? '').split('\n')) {
    const t = MODEL_TRAILER.exec(l.trim());
    if (t) models.add(t[1].trim());
  }
  if (models.size > 1) models.delete('Claude');
  if (!byPr.has(m[1])) byPr.set(m[1], [...models]);
}

let added = 0, skipped = 0;
const missing = new Set();
for (const f of readdirSync(`${root}/${dir}`).filter((f) => f.endsWith('.md'))) {
  const path = `${root}/${dir}/${f}`;
  const out = [];
  const lines = readFileSync(path, 'utf8').split('\n');
  // One entry runs from its `## ` heading to the next; Landed sits at its end, so
  // the whole entry is buffered before the Model line can be placed after Actor.
  let buf = [];
  const flush = () => {
    if (!buf.length) return;
    const landed = /\*\*Landed:\*\*\s*#(\d+)/.exec(buf.join('\n'));
    const models = landed ? byPr.get(landed[1]) : null;
    if (landed && !byPr.has(landed[1])) missing.add(landed[1]);
    if (models?.length && !buf.some((l) => l.startsWith('- **Model:**'))) {
      const at = buf.findIndex((l) => l.startsWith('- **Actor:**'));
      if (at >= 0) {
        let end = at + 1;
        while (end < buf.length && !buf[end].startsWith('- **')) end += 1; // skip the Actor's wrapped lines
        buf.splice(end, 0, `- **Model:** ${models.join(', ')}, per the commit trailer.`);
        added += 1;
      } else skipped += 1;
    } else if (landed) skipped += 1;
    out.push(...buf);
    buf = [];
  };
  for (const l of lines) {
    if (l.startsWith('## ')) flush();
    buf.push(l);
  }
  flush();
  writeFileSync(path, out.join('\n'));
}
console.log(`${dir}: added ${added}, left without a model ${skipped}`);
if (missing.size) console.log(`  PRs with no squash commit on main: ${[...missing].join(' ')}`);
EOF
